input.sparql:
SELECT ?sensor ?zone ?ts WHERE {
  ?sensor a brick:ElectricPower .
  ?sensor brick:hasPropertyType ?ptype .
  ?zone brick:hasSubGraph/brick:isLocationOf ?sensor .
  OPTIONAL { ?zone rdfs:label ?label }
}

SELECT ?point ?type ?zonelbl WHERE {
  ?point a ?type .
  ?point brick:isPointOf ?zone .
  OPTIONAL { ?zone rdfs:label ?zonelbl }
}

SELECT ?point ?type WHERE {
  ?point a ?type .
  ?point brick:isPointOf ?zone .
  FILTER (CONTAINS(str(type), "Electric") || CONTAINS(str(type), "Power") || CONTAINS(str(type), "Lighting"))
}

SELECT ?zone ?lbl ?ifcname WHERE {
  ?zone a brick:Zone .
  OPTIONAL { ?zone rdfs:label ?lbl }
  OPTIONAL { ?zone ref:ifcName ?ifcname }
}

SELECT ?zone ?lbl ?ifcname WHERE {
  FILTER EXISTS { ?x brick:isPointOf ?zone }
  OPTIONAL { ?zone rdfs:label ?lbl }
  OPTIONAL { ?zone ref:ifcName ?ifcname }
}
